def search_disclosure(company_name, start_date, end_date, reprt_code=None, has_xbrl=None, status=None, limit=None, cursor=None, sort=None, **_extra):
    import json, os, datetime, re, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0443000" if __import__("os").path.isdir("./environment_mix/0443000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now.isoformat() + "Z"

    # ---- helpers ----
    def _new_tool_request_id():
        return "dart_treq_" + uuid.uuid4().hex

    def _append_tool_request(status0, resolved_company_id=None, start_date_norm=None, end_date_norm=None, error_message=None):
        rows = _load("tool_requests.json")
        rid = _new_tool_request_id()
        row = {
            "id": rid,
            "tool_name": "search_disclosure",
            "input": {
                "company_name": company_name,
                "start_date": start_date,
                "end_date": end_date,
                "reprt_code": reprt_code,
                "has_xbrl": has_xbrl,
                "status": status,
                "limit": limit,
                "cursor": cursor,
                "sort": sort,
            },
            "resolved_company_id": resolved_company_id,
            "start_date": start_date_norm,
            "end_date": end_date_norm,
            "bsns_year": None,
            "reprt_code": reprt_code,
            "fs_div": None,
            "statement_type": None,
            "information_type": None,
            "status": status0,
            "http_cache_hit": False,
            "error_message": error_message,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        rows.append(row)
        _save("tool_requests.json", rows)
        return rid

    def _transition_tool_request(req_id, to_status, resolved_company_id=None, start_date_norm=None, end_date_norm=None, error_message=None):
        rows = _load("tool_requests.json")
        trans = {"received": ["running", "failed"], "running": ["succeeded", "failed"], "succeeded": [], "failed": []}
        updated = False
        for r in rows:
            if r.get("id") == req_id:
                cur = r.get("status")
                if to_status not in trans.get(cur, []):
                    to_status = "failed"
                    error_message = error_message or "Invalid request lifecycle transition"
                if resolved_company_id is not None:
                    r["resolved_company_id"] = resolved_company_id
                if start_date_norm is not None:
                    r["start_date"] = start_date_norm
                if end_date_norm is not None:
                    r["end_date"] = end_date_norm
                r["status"] = to_status
                r["error_message"] = error_message
                r["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
                updated = True
                break
        if updated:
            _save("tool_requests.json", rows)
        return updated

    def _parse_date_flexible(s):
        # Accept YYYYMMDD (schema) and also ISO-8601 timestamps (audit defect shows these were sent)
        if not isinstance(s, str):
            return None, "date must be string"
        s = s.strip()
        if re.fullmatch(r"\d{8}", s):
            y, m, d = int(s[0:4]), int(s[4:6]), int(s[6:8])
            try:
                return datetime.datetime(y, m, d, 0, 0, 0), None
            except ValueError:
                return None, "invalid YYYYMMDD date"
        # ISO 8601
        try:
            s2 = s
            if s2.endswith("Z"):
                s2 = s2[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s2)
            if dt.tzinfo is not None:
                dt = dt.astimezone(datetime.timezone.utc).replace(tzinfo=None)
            return dt.replace(hour=0, minute=0, second=0, microsecond=0), None
        except ValueError:
            return None, "invalid date format (expected YYYYMMDD or ISO-8601)"

    def _parse_stored_dt(val):
        # Stored datetimes may be ISO with Z; normalize to naive UTC for safe comparisons
        if isinstance(val, datetime.datetime):
            dt = val
            if dt.tzinfo is not None:
                dt = dt.astimezone(datetime.timezone.utc).replace(tzinfo=None)
            return dt
        if not isinstance(val, str) or not val:
            return None
        s = val.strip()
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is not None:
                dt = dt.astimezone(datetime.timezone.utc).replace(tzinfo=None)
            return dt
        except ValueError:
            # best-effort: try YYYY-MM-DD
            try:
                dt = datetime.datetime.strptime(val[0:10], "%Y-%m-%d")
                return dt
            except Exception:
                return None

    def _resolve_company_id_by_name(name):
        companies = _load("companies.json")
        if not isinstance(companies, list):
            return None, "Company datastore unreadable"
        nm = (name or "").strip()
        if not nm:
            return None, "Company name is empty"
        matches = []
        for c in companies:
            if not isinstance(c, dict):
                continue
            if c.get("company_name_ko") == nm:
                matches.append(c)
                continue
            aliases = c.get("name_aliases")
            if isinstance(aliases, list) and nm in aliases:
                matches.append(c)
        # Must resolve to exactly one
        if len(matches) == 0:
            return None, "Company not found"
        if len(matches) > 1:
            return None, "Company name is ambiguous"
        return matches[0].get("id"), None

    # ---- validate input first ----
    req_id = _append_tool_request("received")
    start_dt, err = _parse_date_flexible(start_date)
    if err:
        _transition_tool_request(req_id, "failed", error_message=err)
        return _err("VALIDATION_ERROR", err)
    end_dt, err = _parse_date_flexible(end_date)
    if err:
        _transition_tool_request(req_id, "failed", error_message=err)
        return _err("VALIDATION_ERROR", err)

    # store normalized YYYYMMDD (tool_requests schema expects string)
    start_norm = start_dt.strftime("%Y%m%d")
    end_norm = end_dt.strftime("%Y%m%d")

    if start_dt > end_dt:
        msg = "start_date must be <= end_date"
        _transition_tool_request(req_id, "failed", start_date_norm=start_norm, end_date_norm=end_norm, error_message=msg)
        return _err("VALIDATION_ERROR", msg)

    if reprt_code is not None and reprt_code not in {"11011", "11012", "11013", "11014"}:
        msg = "Invalid reprt_code"
        _transition_tool_request(req_id, "failed", start_date_norm=start_norm, end_date_norm=end_norm, error_message=msg)
        return _err("VALIDATION_ERROR", msg)

    if status is not None and status not in {"indexed", "fetching", "ready", "failed", "archived"}:
        msg = "Invalid status"
        _transition_tool_request(req_id, "failed", start_date_norm=start_norm, end_date_norm=end_norm, error_message=msg)
        return _err("VALIDATION_ERROR", msg)

    if has_xbrl is not None and not isinstance(has_xbrl, bool):
        msg = "has_xbrl must be boolean"
        _transition_tool_request(req_id, "failed", start_date_norm=start_norm, end_date_norm=end_norm, error_message=msg)
        return _err("VALIDATION_ERROR", msg)

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        msg = "limit must be integer between 1 and 200"
        _transition_tool_request(req_id, "failed", start_date_norm=start_norm, end_date_norm=end_norm, error_message=msg)
        return _err("VALIDATION_ERROR", msg)

    if sort is None:
        sort = "-disclosure_date"
    if sort not in {"disclosure_date", "-disclosure_date"}:
        msg = "Invalid sort"
        _transition_tool_request(req_id, "failed", start_date_norm=start_norm, end_date_norm=end_norm, error_message=msg)
        return _err("VALIDATION_ERROR", msg)

    # resolve company
    company_id, cerr = _resolve_company_id_by_name(company_name)
    if cerr:
        _transition_tool_request(req_id, "failed", start_date_norm=start_norm, end_date_norm=end_norm, error_message=cerr)
        return _err("NOT_FOUND", cerr)

    _transition_tool_request(req_id, "running", resolved_company_id=company_id, start_date_norm=start_norm, end_date_norm=end_norm)

    disclosures = _load("disclosures.json")
    if not isinstance(disclosures, list):
        msg = "Disclosure datastore unreadable"
        _transition_tool_request(req_id, "failed", error_message=msg)
        return _err("CONFLICT", msg)

    # filter by company and date range inclusive (midnight boundaries)
    end_exclusive = end_dt + datetime.timedelta(days=1)
    filtered = []
    for d in disclosures:
        if not isinstance(d, dict):
            continue
        if d.get("company_id") != company_id:
            continue
        dt = _parse_stored_dt(d.get("disclosure_date"))
        if dt is None:
            continue
        if not (start_dt <= dt < end_exclusive):
            continue
        if reprt_code is not None and d.get("reprt_code") != reprt_code:
            continue
        if has_xbrl is not None and bool(d.get("has_xbrl")) != has_xbrl:
            continue
        if status is not None and d.get("status") != status:
            continue
        filtered.append(d)

    reverse = (sort == "-disclosure_date")
    filtered.sort(key=lambda x: (_parse_stored_dt(x.get("disclosure_date")) or datetime.datetime.min, x.get("id") or ""), reverse=reverse)

    # cursor is the last seen disclosure id (tolerate bad cursor by treating as start)
    start_idx = 0
    if cursor is not None:
        if not isinstance(cursor, str):
            msg = "cursor must be string"
            _transition_tool_request(req_id, "failed", error_message=msg)
            return _err("VALIDATION_ERROR", msg)
        for i, row in enumerate(filtered):
            if row.get("id") == cursor:
                start_idx = i + 1
                break

    page = filtered[start_idx:start_idx + limit]
    has_more = start_idx + limit < len(filtered)
    next_cursor = page[-1].get("id") if (has_more and page) else None

    _transition_tool_request(req_id, "succeeded")

    return {
        "tool_request_id": req_id,
        "company_id": company_id,
        "start_date": start_norm,
        "end_date": end_norm,
        "sort": sort,
        "limit": limit,
        "cursor": cursor,
        "next_cursor": next_cursor,
        "has_more": has_more,
        "total": len(filtered),
        "disclosures": page,
        "latency_ms": int((time.time() - t0) * 1000),
    }

def search_detailed_financial_data(company_name, start_date, end_date, statement_type=None, **_extra):
    import json, os, datetime, re, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0443000" if __import__("os").path.isdir("./environment_mix/0443000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_iso = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_tool_request_id():
        return "dart_treq_" + uuid.uuid4().hex

    def _append_tool_request(status0, resolved_company_id=None, start_date_norm=None, end_date_norm=None, error_message=None, statement_type_norm=None):
        rows = _load("tool_requests.json")
        rid = _new_tool_request_id()
        row = {
            "id": rid,
            "tool_name": "search_detailed_financial_data",
            "input": {
                "company_name": company_name,
                "start_date": start_date,
                "end_date": end_date,
                "statement_type": statement_type,
            },
            "resolved_company_id": resolved_company_id,
            "start_date": start_date_norm,
            "end_date": end_date_norm,
            "bsns_year": None,
            "reprt_code": None,
            "fs_div": None,
            "statement_type": statement_type_norm if statement_type_norm is not None else statement_type,
            "information_type": None,
            "status": status0,
            "http_cache_hit": False,
            "error_message": error_message,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        rows.append(row)
        _save("tool_requests.json", rows)
        return rid

    def _transition_tool_request(req_id, to_status, resolved_company_id=None, start_date_norm=None, end_date_norm=None, error_message=None, statement_type_norm=None):
        rows = _load("tool_requests.json")
        trans = {"received": ["running", "failed"], "running": ["succeeded", "failed"], "succeeded": [], "failed": []}
        updated = False
        for r in rows:
            if r.get("id") == req_id:
                cur = r.get("status")
                if to_status not in trans.get(cur, []):
                    to_status = "failed"
                    error_message = error_message or "Invalid request lifecycle transition"
                if resolved_company_id is not None:
                    r["resolved_company_id"] = resolved_company_id
                if start_date_norm is not None:
                    r["start_date"] = start_date_norm
                if end_date_norm is not None:
                    r["end_date"] = end_date_norm
                if statement_type_norm is not None:
                    r["statement_type"] = statement_type_norm
                r["status"] = to_status
                r["error_message"] = error_message
                r["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
                updated = True
                break
        if updated:
            _save("tool_requests.json", rows)
        return updated

    def _parse_date_flexible(s):
        if not isinstance(s, str):
            return None, "date must be string"
        s = s.strip()
        if re.fullmatch(r"\d{8}", s):
            y, m, d = int(s[0:4]), int(s[4:6]), int(s[6:8])
            try:
                return datetime.datetime(y, m, d, 0, 0, 0), None
            except ValueError:
                return None, "invalid YYYYMMDD date"
        try:
            s2 = s
            if s2.endswith("Z"):
                s2 = s2[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s2)
            if dt.tzinfo is not None:
                dt = dt.astimezone(datetime.timezone.utc).replace(tzinfo=None)
            return dt.replace(hour=0, minute=0, second=0, microsecond=0), None
        except ValueError:
            return None, "invalid date format (expected YYYYMMDD or ISO-8601)"

    def _parse_stored_dt(val):
        if isinstance(val, datetime.datetime):
            dt = val
            if dt.tzinfo is not None:
                dt = dt.astimezone(datetime.timezone.utc).replace(tzinfo=None)
            return dt
        if not isinstance(val, str) or not val:
            return None
        s = val.strip()
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is not None:
                dt = dt.astimezone(datetime.timezone.utc).replace(tzinfo=None)
            return dt
        except ValueError:
            try:
                return datetime.datetime.strptime(val[0:10], "%Y-%m-%d")
            except Exception:
                return None

    def _resolve_company_id_by_name(name):
        companies = _load("companies.json")
        if not isinstance(companies, list):
            return None, "Company datastore unreadable"
        nm = (name or "").strip()
        if not nm:
            return None, "Company name is empty"
        matches = []
        for c in companies:
            if not isinstance(c, dict):
                continue
            if c.get("company_name_ko") == nm:
                matches.append(c)
                continue
            aliases = c.get("name_aliases")
            if isinstance(aliases, list) and nm in aliases:
                matches.append(c)
        if len(matches) == 0:
            return None, "Company not found"
        if len(matches) > 1:
            return None, "Company name is ambiguous"
        return matches[0].get("id"), None

    # ---- validate ----
    stmt_norm = None
    if statement_type is not None:
        if not isinstance(statement_type, str):
            req_id = _append_tool_request("received")
            _transition_tool_request(req_id, "failed", error_message="statement_type must be string")
            return _err("VALIDATION_ERROR", "statement_type must be string")
        mapping = {"재무상태표": "BS", "손익계산서": "IS", "현금흐름표": "CF"}
        if statement_type not in mapping:
            req_id = _append_tool_request("received")
            _transition_tool_request(req_id, "failed", error_message="Invalid statement_type")
            return _err("VALIDATION_ERROR", "Invalid statement_type")
        stmt_norm = mapping[statement_type]

    req_id = _append_tool_request("received", statement_type_norm=stmt_norm)

    start_dt, err = _parse_date_flexible(start_date)
    if err:
        _transition_tool_request(req_id, "failed", error_message=err)
        return _err("VALIDATION_ERROR", err)
    end_dt, err = _parse_date_flexible(end_date)
    if err:
        _transition_tool_request(req_id, "failed", error_message=err)
        return _err("VALIDATION_ERROR", err)
    start_norm = start_dt.strftime("%Y%m%d")
    end_norm = end_dt.strftime("%Y%m%d")
    if start_dt > end_dt:
        msg = "start_date must be <= end_date"
        _transition_tool_request(req_id, "failed", start_date_norm=start_norm, end_date_norm=end_norm, error_message=msg, statement_type_norm=stmt_norm)
        return _err("VALIDATION_ERROR", msg)

    company_id, cerr = _resolve_company_id_by_name(company_name)
    if cerr:
        _transition_tool_request(req_id, "failed", start_date_norm=start_norm, end_date_norm=end_norm, error_message=cerr, statement_type_norm=stmt_norm)
        return _err("NOT_FOUND", cerr)

    _transition_tool_request(req_id, "running", resolved_company_id=company_id, start_date_norm=start_norm, end_date_norm=end_norm, statement_type_norm=stmt_norm)

    disclosures = _load("disclosures.json")
    if not isinstance(disclosures, list):
        msg = "Disclosure datastore unreadable"
        _transition_tool_request(req_id, "failed", error_message=msg)
        return _err("CONFLICT", msg)

    end_exclusive = end_dt + datetime.timedelta(days=1)
    d_in_range = []
    for d in disclosures:
        if not isinstance(d, dict):
            continue
        if d.get("company_id") != company_id:
            continue
        dt = _parse_stored_dt(d.get("disclosure_date"))
        if dt is None:
            continue
        if start_dt <= dt < end_exclusive:
            d_in_range.append(d)

    # latest disclosure first (business rule: representative/latest)
    d_in_range.sort(key=lambda x: (_parse_stored_dt(x.get("disclosure_date")) or datetime.datetime.min, x.get("id") or ""), reverse=True)
    disclosure_ids = [d.get("id") for d in d_in_range if d.get("id")]

    items = _load("financial_statement_items.json")
    arts = _load("source_artifacts.json")
    if not isinstance(items, list) or not isinstance(arts, list):
        msg = "Datastore unreadable"
        _transition_tool_request(req_id, "failed", error_message=msg)
        return _err("CONFLICT", msg)

    art_by_id = {a.get("id"): a for a in arts if isinstance(a, dict) and a.get("id")}
    preferred_art_types = {"xbrl_instance", "xbrl_zip"}

    def _item_matches(it):
        if not isinstance(it, dict):
            return False
        if it.get("company_id") != company_id:
            return False
        if it.get("status") == "superseded":
            return False
        if it.get("disclosure_id") not in disclosure_ids:
            return False
        if stmt_norm is not None and it.get("statement_type") != stmt_norm:
            return False
        return True

    candidates = [it for it in items if _item_matches(it)]

    def _is_preferred(it):
        aid = it.get("source_artifact_id")
        a = art_by_id.get(aid) if aid else None
        if not a:
            return False
        return (a.get("artifact_type") in preferred_art_types) and (a.get("parse_status") == "parsed")

    preferred = [it for it in candidates if _is_preferred(it)]
    chosen_pool = preferred if preferred else candidates  # fallback allowed

    # If none exist at all, succeed with empty set (tool description allows empty/NOT_FOUND; business rules don't require error)
    # We'll return empty and succeed.
    # choose latest disclosure as representative, but return all items tied to that disclosure if present; otherwise all in range.
    rep_disclosure_id = disclosure_ids[0] if disclosure_ids else None
    if rep_disclosure_id:
        rep_items = [it for it in chosen_pool if it.get("disclosure_id") == rep_disclosure_id]
    else:
        rep_items = []

    result_items = rep_items if rep_items else chosen_pool

    # stable sort: disclosure_date desc then statement_type
    disclosure_date_by_id = {}
    for d in d_in_range:
        did = d.get("id")
        if did and did not in disclosure_date_by_id:
            disclosure_date_by_id[did] = _parse_stored_dt(d.get("disclosure_date"))

    result_items.sort(
        key=lambda it: (
            disclosure_date_by_id.get(it.get("disclosure_id")) or datetime.datetime.min,
            it.get("statement_type") or "",
            it.get("account_name") or "",
            it.get("period_end") or "",
            it.get("id") or "",
        ),
        reverse=True
    )

    _transition_tool_request(req_id, "succeeded")

    return {
        "tool_request_id": req_id,
        "company_id": company_id,
        "start_date": start_norm,
        "end_date": end_norm,
        "statement_type": stmt_norm,
        "representative_disclosure_id": rep_disclosure_id,
        "preferred_source_used": True if preferred else False,
        "total": len(result_items),
        "items": result_items,
        "latency_ms": int((time.time() - t0) * 1000),
    }

def search_business_information(company_name, start_date, end_date, information_type, **_extra):
