            "statement_type": None,
            "information_type": information_type,
            "status": status0,
            "http_cache_hit": False,
            "error_message": error_message,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        rows.append(row)
        _save("tool_requests.json", rows)
        return rid

    def _transition_tool_request(req_id, to_status, resolved_company_id=None, start_date_norm=None, end_date_norm=None, error_message=None):
        rows = _load("tool_requests.json")
        trans = {"received": ["running", "failed"], "running": ["succeeded", "failed"], "succeeded": [], "failed": []}
        updated = False
        for r in rows:
            if r.get("id") == req_id:
                cur = r.get("status")
                if to_status not in trans.get(cur, []):
                    to_status = "failed"
                    error_message = error_message or "Invalid request lifecycle transition"
                if resolved_company_id is not None:
                    r["resolved_company_id"] = resolved_company_id
                if start_date_norm is not None:
                    r["start_date"] = start_date_norm
                if end_date_norm is not None:
                    r["end_date"] = end_date_norm
                r["status"] = to_status
                r["error_message"] = error_message
                r["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
                updated = True
                break
        if updated:
            _save("tool_requests.json", rows)
        return updated

    def _parse_date_flexible(s):
        if not isinstance(s, str):
            return None, "date must be string"
        s = s.strip()
        if re.fullmatch(r"\d{8}", s):
            y, m, d = int(s[0:4]), int(s[4:6]), int(s[6:8])
            try:
                return datetime.datetime(y, m, d, 0, 0, 0), None
            except ValueError:
                return None, "invalid YYYYMMDD date"
        try:
            s2 = s
            if s2.endswith("Z"):
                s2 = s2[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s2)
            if dt.tzinfo is not None:
                dt = dt.astimezone(datetime.timezone.utc).replace(tzinfo=None)
            return dt.replace(hour=0, minute=0, second=0, microsecond=0), None
        except ValueError:
            return None, "invalid date format (expected YYYYMMDD or ISO-8601)"

    def _parse_stored_dt(val):
        if isinstance(val, datetime.datetime):
            dt = val
            if dt.tzinfo is not None:
                dt = dt.astimezone(datetime.timezone.utc).replace(tzinfo=None)
            return dt
        if not isinstance(val, str) or not val:
            return None
        s = val.strip()
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is not None:
                dt = dt.astimezone(datetime.timezone.utc).replace(tzinfo=None)
            return dt
        except ValueError:
            try:
                return datetime.datetime.strptime(val[0:10], "%Y-%m-%d")
            except Exception:
                return None

    def _resolve_company_id_by_name(name):
        companies = _load("companies.json")
        if not isinstance(companies, list):
            return None, "Company datastore unreadable"
        nm = (name or "").strip()
        if not nm:
            return None, "Company name is empty"
        matches = []
        for c in companies:
            if not isinstance(c, dict):
                continue
            if c.get("company_name_ko") == nm:
                matches.append(c)
                continue
            aliases = c.get("name_aliases")
            if isinstance(aliases, list) and nm in aliases:
                matches.append(c)
        if len(matches) == 0:
            return None, "Company not found"
        if len(matches) > 1:
            return None, "Company name is ambiguous"
        return matches[0].get("id"), None

    allowed_info = {"사업의 개요", "주요 제품 및 서비스", "원재료 및 생산설비", "매출 및 수주상황", "위험관리 및 파생거래", "주요계약 및 연구개발활동", "기타 참고사항"}

    req_id = _append_tool_request("received")

    if information_type not in allowed_info:
        msg = "Invalid information_type"
        _transition_tool_request(req_id, "failed", error_message=msg)
        return _err("VALIDATION_ERROR", msg)

    start_dt, err = _parse_date_flexible(start_date)
    if err:
        _transition_tool_request(req_id, "failed", error_message=err)
        return _err("VALIDATION_ERROR", err)
    end_dt, err = _parse_date_flexible(end_date)
    if err:
        _transition_tool_request(req_id, "failed", error_message=err)
        return _err("VALIDATION_ERROR", err)

    start_norm = start_dt.strftime("%Y%m%d")
    end_norm = end_dt.strftime("%Y%m%d")

    if start_dt > end_dt:
        msg = "start_date must be <= end_date"
        _transition_tool_request(req_id, "failed", start_date_norm=start_norm, end_date_norm=end_norm, error_message=msg)
        return _err("VALIDATION_ERROR", msg)

    company_id, cerr = _resolve_company_id_by_name(company_name)
    if cerr:
        _transition_tool_request(req_id, "failed", start_date_norm=start_norm, end_date_norm=end_norm, error_message=cerr)
        return _err("NOT_FOUND", cerr)

    _transition_tool_request(req_id, "running", resolved_company_id=company_id, start_date_norm=start_norm, end_date_norm=end_norm)

    disclosures = _load("disclosures.json")
    sections = _load("business_information_sections.json")
    if not isinstance(disclosures, list) or not isinstance(sections, list):
        msg = "Datastore unreadable"
        _transition_tool_request(req_id, "failed", error_message=msg)
        return _err("CONFLICT", msg)

    end_exclusive = end_dt + datetime.timedelta(days=1)

    # disclosures in range (including archived per retention rule)
    d_in_range = []
    for d in disclosures:
        if not isinstance(d, dict):
            continue
        if d.get("company_id") != company_id:
            continue
        dt = _parse_stored_dt(d.get("disclosure_date"))
        if dt is None:
            continue
        if start_dt <= dt < end_exclusive:
            d_in_range.append(d)

    disclosure_dt = {d.get("id"): _parse_stored_dt(d.get("disclosure_date")) for d in d_in_range if d.get("id")}
    disclosure_ids = set([d.get("id") for d in d_in_range if d.get("id")])

    # candidate sections for disclosures in range and requested type
    candidates = []
    for s in sections:
        if not isinstance(s, dict):
            continue
        if s.get("company_id") != company_id:
            continue
        did = s.get("disclosure_id")
        if did not in disclosure_ids:
            continue
        if s.get("information_type") != information_type:
            continue
        candidates.append(s)

    # Prefer latest disclosure_date for same information_type (default)
    def _cand_key(sec):
        dt = disclosure_dt.get(sec.get("disclosure_id")) or datetime.datetime.min
        return (dt, sec.get("updated_at") or "", sec.get("id") or "")

    candidates.sort(key=_cand_key, reverse=True)

    # Return only the latest one (default behavior per rule); but keep envelope consistent.
    chosen = candidates[0:1] if candidates else []

    _transition_tool_request(req_id, "succeeded")

    return {
        "tool_request_id": req_id,
        "company_id": company_id,
        "start_date": start_norm,
        "end_date": end_norm,
        "information_type": information_type,
        "total": len(chosen),
        "sections": chosen,
        "latency_ms": int((time.time() - t0) * 1000),
    }

def search_json_financial_data(company_name, bsns_year, reprt_code, fs_div, statement_type, **_extra):
    import json, os, datetime, re, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0443000" if __import__("os").path.isdir("./environment_mix/0443000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now.isoformat() + "Z"

    TRANS_REQ = {
        "received": ["running", "failed"],
        "running": ["succeeded", "failed"],
        "succeeded": [],
        "failed": [],
    }

    def _new_id(prefix):
        # keep vendor-like id shape but deterministic enough; uuid ok
        return f"{prefix}_{uuid.uuid4().hex}"

    def _append_tool_request(input_payload, status0, resolved_company_id=None, error_message=None):
        rows = _load("tool_requests.json")
        rid = _new_id("dart_treq")
        ip = input_payload if isinstance(input_payload, dict) else {}
        row = {
            "id": rid,
            "tool_name": "search_json_financial_data",
            "input": ip,
            "resolved_company_id": resolved_company_id,
            "start_date": None,
            "end_date": None,
            "bsns_year": str(ip.get("bsns_year")) if ip.get("bsns_year") is not None else None,
            "reprt_code": ip.get("reprt_code"),
            "fs_div": ip.get("fs_div"),
            "statement_type": ip.get("statement_type"),
            "information_type": None,
            "status": status0,
            "http_cache_hit": False,
            "error_message": error_message,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        rows.append(row)
        _save("tool_requests.json", rows)
        return rid

    def _transition_tool_request(req_id, to_status, resolved_company_id=None, error_message=None):
        rows = _load("tool_requests.json")
        for r in rows:
            if r.get("id") == req_id:
                cur = r.get("status")
                if cur not in TRANS_REQ or to_status not in TRANS_REQ.get(cur, []):
                    return False
                r["status"] = to_status
                r["updated_at"] = now_iso
                if resolved_company_id is not None:
                    r["resolved_company_id"] = resolved_company_id
                if error_message is not None:
                    r["error_message"] = error_message
                _save("tool_requests.json", rows)
                return True
        return False

    def _fail(req_id, code, msg, resolved_company_id=None, **extra):
        _transition_tool_request(req_id, "failed", resolved_company_id=resolved_company_id, error_message=msg)
        latency_ms = int((time.time() - t0) * 1000)
        return _err(code, msg, tool_request_id=req_id, latency_ms=latency_ms, **extra)

    def _succeed(req_id, resolved_company_id=None):
        _transition_tool_request(req_id, "succeeded", resolved_company_id=resolved_company_id)
        return True

    # --- Audit row: received -> running -> (succeeded|failed)
    input_payload = {
        "company_name": company_name,
        "bsns_year": bsns_year,
        "reprt_code": reprt_code,
        "fs_div": fs_div,
        "statement_type": statement_type,
    }
    req_id = _append_tool_request(input_payload, "received")
    if not _transition_tool_request(req_id, "running"):
        # should not happen unless store is corrupted
        return _err("CONFLICT", "Could not start request", tool_request_id=req_id)

    # --- Validate inputs (relaxed: accept bsns_year as int too; normalize to 4-digit string)
    if not isinstance(company_name, str) or not company_name.strip():
        return _fail(req_id, "VALIDATION_ERROR", "company_name must be a non-empty string")

    if isinstance(bsns_year, int):
        bsns_year_str = f"{bsns_year:04d}"
    elif isinstance(bsns_year, str):
        bsns_year_str = bsns_year
    else:
        return _fail(req_id, "VALIDATION_ERROR", "bsns_year must be a 4-digit string (or integer year)")
    if not re.fullmatch(r"\d{4}", bsns_year_str or ""):
        return _fail(req_id, "VALIDATION_ERROR", "bsns_year must match ^\\d{4}$", bsns_year=str(bsns_year))

    if reprt_code not in {"11011", "11012", "11013", "11014"}:
        return _fail(req_id, "VALIDATION_ERROR", "Invalid reprt_code", reprt_code=reprt_code)

    if fs_div not in {"OFS", "CFS"}:
        return _fail(req_id, "VALIDATION_ERROR", "Invalid fs_div", fs_div=fs_div)

    if statement_type not in {"BS", "IS", "CF"}:
        return _fail(req_id, "VALIDATION_ERROR", "Invalid statement_type", statement_type=statement_type)

    bsns_year_int = int(bsns_year_str)

    # --- Resolve company (must resolve exactly one by exact ko name or alias)
    companies = _load("companies.json")
    matches = []
    for c in companies:
        if c.get("company_name_ko") == company_name:
            matches.append(c)
            continue
        aliases = c.get("name_aliases") or []
        if isinstance(aliases, list) and company_name in aliases:
            matches.append(c)
    # de-dupe by id
    uniq = {}
    for c in matches:
        cid = c.get("id")
        if cid:
            uniq[cid] = c
    matches = list(uniq.values())

    if len(matches) == 0:
        return _fail(req_id, "NOT_FOUND", "Company not found", company_name=company_name)
    if len(matches) > 1:
        return _fail(
            req_id,
            "CONFLICT",
            "Ambiguous company_name; multiple companies matched",
            company_name=company_name,
            matched_company_ids=[c.get("id") for c in matches if c.get("id")],
        )

    company = matches[0]
    company_id = company.get("id")
    _transition_tool_request(req_id, "running", resolved_company_id=company_id)

    # --- Find existing financial_statement_items first (should not error if present)
    fsi = _load("financial_statement_items.json")
    artifacts = _load("source_artifacts.json")
    art_by_id = {a.get("id"): a for a in artifacts if a.get("id")}

    def _is_art_json(art_id):
        a = art_by_id.get(art_id)
        return bool(a) and a.get("artifact_type") == "json_financial_api"

    existing = []
    for it in fsi:
        if it.get("company_id") != company_id:
            continue
        if it.get("bsns_year") != bsns_year_int:
            continue
        if it.get("reprt_code") != reprt_code:
            continue
        if it.get("fs_div") != fs_div:
            continue
        if it.get("statement_type") != statement_type:
            continue
        # this tool returns the current view; do not include superseded
        if it.get("status") == "superseded":
            continue
        existing.append(it)

    # Ensure json artifact exists for "most relevant disclosure" (and bind rows if missing)
    disclosures = _load("disclosures.json")
    dsc_by_id = {d.get("id"): d for d in disclosures if d.get("id")}

    # Most relevant disclosure: same company, matching year & reprt_code if possible, latest disclosure_date
    def _parse_dt(x):
        if not isinstance(x, str) or not x:
            return None
        try:
            return datetime.datetime.fromisoformat(x.replace("Z", "+00:00")).replace(tzinfo=None)
        except Exception:
            return None

    candidates = []
    for d in disclosures:
        if d.get("company_id") != company_id:
            continue
        if d.get("reprt_code") != reprt_code:
            continue
        by = d.get("bsns_year")
        if by is not None and isinstance(by, int) and by != bsns_year_int:
            continue
        candidates.append(d)

    if not candidates:
        # fallback: any disclosure for the company, latest date
        for d in disclosures:
            if d.get("company_id") == company_id:
                candidates.append(d)

    chosen = None
    if candidates:
        candidates.sort(key=lambda d: (_parse_dt(d.get("disclosure_date")) or datetime.datetime.min, d.get("id") or ""), reverse=True)
        chosen = candidates[0]

    # Create or reuse json_financial_api artifact for chosen disclosure (if any)
    json_artifact = None
    if chosen and chosen.get("id"):
        disclosure_id = chosen.get("id")
        for a in artifacts:
            if a.get("disclosure_id") == disclosure_id and a.get("artifact_type") == "json_financial_api":
                json_artifact = a
                break
        if json_artifact is None:
            # Data retention rule: do not create new writes if disclosure is archived
            if chosen.get("status") == "archived":
                # We can still return existing items; but cannot create new artifact/ingestions
                json_artifact = None
            else:
                new_art = {
                    "id": _new_id("dart_art"),
                    "disclosure_id": disclosure_id,
                    "artifact_type": "json_financial_api",
                    "source_url": None,
                    "storage_key": None,
                    "content_sha256": None,
                    "fetched_at": None,
                    "parse_status": "not_parsed",
                    "parse_error": None,
                    "created_at": now_iso,
                    "updated_at": now_iso,
                }
                artifacts.append(new_art)
                _save("source_artifacts.json", artifacts)
                art_by_id[new_art["id"]] = new_art
                json_artifact = new_art

        # If we have existing items but none linked to json artifact, bind them when safe
        # (This is a normalization fix and counts as ingestion metadata; disallowed if archived)
        if existing and json_artifact is not None and chosen.get("status") != "archived":
            changed = False
            for it in fsi:
                if it.get("id") in {e.get("id") for e in existing}:
                    if not it.get("source_artifact_id"):
                        it["source_artifact_id"] = json_artifact.get("id")
                        it["updated_at"] = now_iso
                        changed = True
            if changed:
                _save("financial_statement_items.json", fsi)

    # Recompute existing after possible binding (still read-only in outcome)
    fsi = _load("financial_statement_items.json")
    artifacts = _load("source_artifacts.json")
    art_by_id = {a.get("id"): a for a in artifacts if a.get("id")}
    existing = []
    for it in fsi:
        if it.get("company_id") != company_id:
            continue
        if it.get("bsns_year") != bsns_year_int:
            continue
        if it.get("reprt_code") != reprt_code:
            continue
        if it.get("fs_div") != fs_div:
            continue
        if it.get("statement_type") != statement_type:
            continue
        if it.get("status") == "superseded":
            continue
        existing.append(it)

    # If there are items, succeed and return them (do not incorrectly NOT_FOUND)
    if existing:
        _succeed(req_id, resolved_company_id=company_id)
        latency_ms = int((time.time() - t0) * 1000)
        # stable ordering for callers
        existing.sort(key=lambda r: ((r.get("period_end") or ""), (r.get("account_name") or ""), (r.get("account_code") or ""), (r.get("id") or "")))
        return {
            "tool_request_id": req_id,
            "company_id": company_id,
            "bsns_year": bsns_year_int,
            "reprt_code": reprt_code,
            "fs_div": fs_div,
            "statement_type": statement_type,
            "items": existing,
            "meta": {"count": len(existing), "latency_ms": latency_ms},
        }

    # No existing normalized rows. Per service rules, attempt to "create or reuse" json artifact and write normalized rows.
    # Offline datastore cannot fetch upstream; if we cannot write new rows due to archived disclosure, return NOT_FOUND.
    if chosen is None or not chosen.get("id"):
        return _fail(
            req_id,
            "NOT_FOUND",
            "No relevant disclosure found for company/year/report; cannot retrieve JSON financial data",
            resolved_company_id=company_id,
            company_id=company_id,
            bsns_year=str(bsns_year_int),
            reprt_code=reprt_code,
            fs_div=fs_div,
            statement_type=statement_type,
        )

    if chosen.get("status") == "archived":
        return _fail(
            req_id,
            "NOT_FOUND",
            "No financial statement items for given parameters (writes disallowed for archived disclosures)",
            resolved_company_id=company_id,
            company_id=company_id,
            bsns_year=str(bsns_year_int),
            reprt_code=reprt_code,
            fs_div=fs_div,
            statement_type=statement_type,
        )

    # We can create artifact (already done above) but cannot fabricate new financial rows without upstream payload.
    # Therefore, the real effect possible here is only ensuring the artifact row exists; if after that still no items -> NOT_FOUND.
    return _fail(
        req_id,
        "NOT_FOUND",
        "No financial statement items for given parameters",
        resolved_company_id=company_id,
        company_id=company_id,
        bsns_year=str(bsns_year_int),
        reprt_code=reprt_code,
        fs_div=fs_div,
        statement_type=statement_type,
    )

def search_company(query, status=None, limit=None, cursor=None, sort=None, exact=None, **_extra):
    import json, os, datetime, re, time, uuid, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0443000" if __import__("os").path.isdir("./environment_mix/0443000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _tool_log(status_v, error_message=None):
        tool_requests = _load("tool_requests.json")
        req_id = _new_id("treq")
        row = {
            "id": req_id,
            "tool_name": "search_disclosure",  # tool_requests enum doesn't include search_company; log under closest public search tool
            "input": {
                "query": query,
                "status": status,
                "limit": limit,
                "cursor": cursor,
                "sort": sort,
                "exact": exact,
            },
            "resolved_company_id": None,
            "start_date": None,
            "end_date": None,
            "bsns_year": None,
            "reprt_code": None,
            "fs_div": None,
            "statement_type": None,
            "information_type": None,
            "status": status_v,
            "http_cache_hit": False,
            "error_message": error_message,
            "created_at": now,
            "updated_at": now,
        }
        tool_requests.append(row)
        _save("tool_requests.json", tool_requests)
        return req_id

    def _tool_transition(req_id, to_status, error_message=None):
        tool_requests = _load("tool_requests.json")
        trans = {"received": ["running", "failed"], "running": ["succeeded", "failed"], "succeeded": [], "failed": []}
        for r in tool_requests:
            if r.get("id") == req_id:
                cur = r.get("status")
                if to_status not in trans.get(cur, []):
                    r["updated_at"] = now
                    _save("tool_requests.json", tool_requests)
                    return False
                r["status"] = to_status
                r["updated_at"] = now
                if error_message is not None:
                    r["error_message"] = error_message
                _save("tool_requests.json", tool_requests)
                return True
        return False

    req_id = _tool_log("received")

    # validation
    if not isinstance(query, str) or not query.strip():
        _tool_transition(req_id, "failed", "query must be a non-empty string")
        return _err("VALIDATION_ERROR", "query must be a non-empty string", request_id=req_id)
    if status is not None and status not in {"active", "inactive", "merged"}:
        _tool_transition(req_id, "failed", "invalid status")
        return _err("VALIDATION_ERROR", "status must be one of active/inactive/merged", request_id=req_id)
    if limit is None:
        limit_v = 50
    else:
        if not isinstance(limit, int):
            _tool_transition(req_id, "failed", "limit must be integer")
            return _err("VALIDATION_ERROR", "limit must be integer", request_id=req_id)
        if limit < 1 or limit > 200:
            _tool_transition(req_id, "failed", "limit out of range")
            return _err("VALIDATION_ERROR", "limit must be between 1 and 200", request_id=req_id)
        limit_v = limit
    if sort is None:
        sort_v = "company_name_ko"
    else:
        if sort not in {"company_name_ko", "-company_name_ko", "created_at", "-created_at"}:
            _tool_transition(req_id, "failed", "invalid sort")
            return _err("VALIDATION_ERROR", "sort must be one of company_name_ko/-company_name_ko/created_at/-created_at", request_id=req_id)
        sort_v = sort
    if exact is None:
        exact_v = False
    else:
        if not isinstance(exact, bool):
            _tool_transition(req_id, "failed", "exact must be boolean")
            return _err("VALIDATION_ERROR", "exact must be boolean", request_id=req_id)
        exact_v = exact

    # cursor decode (offset)
    offset = 0
    if cursor is not None:
        if not isinstance(cursor, str):
            _tool_transition(req_id, "failed", "cursor must be string")
            return _err("VALIDATION_ERROR", "cursor must be string", request_id=req_id)
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
            s = raw.decode("utf-8")
            if not s.startswith("offset:"):
                _tool_transition(req_id, "failed", "invalid cursor")
                return _err("VALIDATION_ERROR", "invalid cursor", request_id=req_id)
            offset = int(s.split(":", 1)[1])
            if offset < 0:
                raise ValueError("neg")
        except Exception:
            _tool_transition(req_id, "failed", "invalid cursor")
            return _err("VALIDATION_ERROR", "invalid cursor", request_id=req_id)

    _tool_transition(req_id, "running")

    companies = _load("companies.json")
    q = query.strip()
    q_lower = q.lower()

    def _match(c):
        if status is not None and c.get("status") != status:
            return False
        name_ko = c.get("company_name_ko") or ""
        name_en = c.get("company_name_en") or ""
        aliases = c.get("name_aliases") or []
        if not isinstance(aliases, list):
            aliases = []
        if exact_v:
            if name_ko == q:
                return True
            return q in aliases
        # partial: ko/en contains, alias contains
        if q in name_ko:
            return True
        if q_lower and q_lower in (name_en.lower() if isinstance(name_en, str) else ""):
            return True
        for a in aliases:
            if not isinstance(a, str):
                continue
            if q in a or (q_lower and q_lower in a.lower()):
                return True
        return False

    rows = [c for c in companies if _match(c)]

    def _dt(s):
        if not isinstance(s, str):
            return datetime.datetime.min
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return datetime.datetime.min

    reverse = sort_v.startswith("-")
    keyf = sort_v[1:] if reverse else sort_v
    if keyf == "company_name_ko":
        rows.sort(key=lambda r: (r.get("company_name_ko") or "", r.get("id") or ""), reverse=reverse)
    elif keyf == "created_at":
        rows.sort(key=lambda r: (_dt(r.get("created_at")), r.get("id") or ""), reverse=reverse)

    total = len(rows)
    page = rows[offset:offset + limit_v]
    next_off = offset + len(page)
    has_more = next_off < total
    next_cursor = None
    if has_more:
        token = f"offset:{next_off}".encode("utf-8")
        next_cursor = base64.urlsafe_b64encode(token).decode("utf-8").rstrip("=")

    _tool_transition(req_id, "succeeded")
    return {
        "request_id": req_id,
        "data": page,
        "meta": {
            "query": query,
            "status": status,
            "sort": sort_v,
            "limit": limit_v,
            "cursor": cursor,
            "total": total,
            "has_more": has_more,
            "next_cursor": next_cursor,
            "latency_ms": int((time.time() - t0) * 1000),
        }
    }

def get_company(company_id, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0443000" if __import__("os").path.isdir("./environment_mix/0443000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _tool_log(status_v, error_message=None):
        tool_requests = _load("tool_requests.json")
        req_id = _new_id("treq")
        row = {
            "id": req_id,
            "tool_name": "search_disclosure",  # tool_requests enum doesn't include get_company; log under closest public search tool
            "input": {"company_id": company_id},
            "resolved_company_id": None,
            "start_date": None,
            "end_date": None,
            "bsns_year": None,
            "reprt_code": None,
            "fs_div": None,
            "statement_type": None,
            "information_type": None,
            "status": status_v,
            "http_cache_hit": False,
            "error_message": error_message,
            "created_at": now,
            "updated_at": now,
        }
        tool_requests.append(row)
        _save("tool_requests.json", tool_requests)
        return req_id

    def _tool_transition(req_id, to_status, error_message=None):
        tool_requests = _load("tool_requests.json")
        trans = {"received": ["running", "failed"], "running": ["succeeded", "failed"], "succeeded": [], "failed": []}
        for r in tool_requests:
            if r.get("id") == req_id:
                cur = r.get("status")
                if to_status not in trans.get(cur, []):
                    r["updated_at"] = now
                    _save("tool_requests.json", tool_requests)
                    return False
                r["status"] = to_status
                r["updated_at"] = now
                if error_message is not None:
                    r["error_message"] = error_message
                _save("tool_requests.json", tool_requests)
                return True
        return False

    req_id = _tool_log("received")

    if not isinstance(company_id, str) or not company_id.strip():
        _tool_transition(req_id, "failed", "company_id must be a non-empty string")
        return _err("VALIDATION_ERROR", "company_id must be a non-empty string", request_id=req_id)

    _tool_transition(req_id, "running")

    companies = _load("companies.json")
    found = None
    for c in companies:
        if c.get("id") == company_id:
            found = c
            break

    if found is None:
        _tool_transition(req_id, "failed", "company not found")
        return _err("NOT_FOUND", "company not found", request_id=req_id)

    _tool_transition(req_id, "succeeded")
    return {
        "request_id": req_id,
        "data": found,
        "meta": {"latency_ms": int((time.time() - t0) * 1000)}
    }

def list_source_artifacts(disclosure_id=None, rcept_no=None, artifact_type=None, parse_status=None, limit=None, cursor=None, sort=None, **_extra):
    import json, os, datetime, time, uuid, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0443000" if __import__("os").path.isdir("./environment_mix/0443000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_id(prefix):
