            "input": {
                "disclosure_id": disclosure_id,
                "rcept_no": rcept_no,
                "artifact_type": artifact_type,
                "parse_status": parse_status,
                "limit": limit,
                "cursor": cursor,
                "sort": sort,
            },
            "resolved_company_id": None,
            "start_date": None,
            "end_date": None,
            "bsns_year": None,
            "reprt_code": None,
            "fs_div": None,
            "statement_type": None,
            "information_type": None,
            "status": status_v,
            "http_cache_hit": False,
            "error_message": error_message,
            "created_at": now,
            "updated_at": now,
        }
        tool_requests.append(row)
        _save("tool_requests.json", tool_requests)
        return req_id

    def _tool_transition(req_id, to_status, error_message=None):
        tool_requests = _load("tool_requests.json")
        trans = {"received": ["running", "failed"], "running": ["succeeded", "failed"], "succeeded": [], "failed": []}
        for r in tool_requests:
            if r.get("id") == req_id:
                cur = r.get("status")
                if to_status not in trans.get(cur, []):
                    r["updated_at"] = now
                    _save("tool_requests.json", tool_requests)
                    return False
                r["status"] = to_status
                r["updated_at"] = now
                if error_message is not None:
                    r["error_message"] = error_message
                _save("tool_requests.json", tool_requests)
                return True
        return False

    req_id = _tool_log("received")

    # validation
    if disclosure_id is not None and (not isinstance(disclosure_id, str) or not disclosure_id.strip()):
        _tool_transition(req_id, "failed", "disclosure_id must be a string")
        return _err("VALIDATION_ERROR", "disclosure_id must be a string", request_id=req_id)
    if rcept_no is not None and (not isinstance(rcept_no, str) or not rcept_no.strip()):
        _tool_transition(req_id, "failed", "rcept_no must be a string")
        return _err("VALIDATION_ERROR", "rcept_no must be a string", request_id=req_id)

    allowed_artifact_type = {"xbrl_instance", "xbrl_zip", "json_financial_api", "pdf", "html", "other"}
    if artifact_type is not None:
        if artifact_type not in allowed_artifact_type:
            _tool_transition(req_id, "failed", "invalid artifact_type")
            return _err("VALIDATION_ERROR", "artifact_type is invalid", request_id=req_id)

    if parse_status is not None:
        if parse_status not in {"not_parsed", "parsing", "parsed", "parse_failed"}:
            _tool_transition(req_id, "failed", "invalid parse_status")
            return _err("VALIDATION_ERROR", "parse_status is invalid", request_id=req_id)

    if limit is None:
        limit_v = 50
    else:
        if not isinstance(limit, int):
            _tool_transition(req_id, "failed", "limit must be integer")
            return _err("VALIDATION_ERROR", "limit must be integer", request_id=req_id)
        if limit < 1 or limit > 200:
            _tool_transition(req_id, "failed", "limit out of range")
            return _err("VALIDATION_ERROR", "limit must be between 1 and 200", request_id=req_id)
        limit_v = limit

    if sort is None:
        sort_v = "-created_at"
    else:
        if sort not in {"created_at", "-created_at", "fetched_at", "-fetched_at"}:
            _tool_transition(req_id, "failed", "invalid sort")
            return _err("VALIDATION_ERROR", "sort is invalid", request_id=req_id)
        sort_v = sort

    # cursor decode offset
    offset = 0
    if cursor is not None:
        if not isinstance(cursor, str):
            _tool_transition(req_id, "failed", "cursor must be string")
            return _err("VALIDATION_ERROR", "cursor must be string", request_id=req_id)
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
            s = raw.decode("utf-8")
            if not s.startswith("offset:"):
                _tool_transition(req_id, "failed", "invalid cursor")
                return _err("VALIDATION_ERROR", "invalid cursor", request_id=req_id)
            offset = int(s.split(":", 1)[1])
            if offset < 0:
                raise ValueError("neg")
        except Exception:
            _tool_transition(req_id, "failed", "invalid cursor")
            return _err("VALIDATION_ERROR", "invalid cursor", request_id=req_id)

    # resolve disclosure via rcept_no if provided
    resolved_disclosure_id = None
    if disclosure_id is not None:
        resolved_disclosure_id = disclosure_id.strip()

    if resolved_disclosure_id is None and rcept_no is not None:
        disclosures = _load("disclosures.json")
        for d in disclosures:
            if d.get("rcept_no") == rcept_no.strip():
                resolved_disclosure_id = d.get("id")
                break
        # if no disclosure found, return empty success (per contract: reads with filters match nothing -> empty set)
        # so keep None to filter to empty
        if resolved_disclosure_id is None:
            _tool_transition(req_id, "running")
            _tool_transition(req_id, "succeeded")
            return {
                "request_id": req_id,
                "data": [],
                "meta": {
                    "total": 0,
                    "has_more": False,
                    "next_cursor": None,
                    "latency_ms": int((time.time() - t0) * 1000),
                }
            }

    _tool_transition(req_id, "running")

    artifacts = _load("source_artifacts.json")
    # map tool-level artifact_type to store enum where possible
    # store enums: xbrl_zip, xbrl_instance, json_financial_api, html_report_section, other_attachment
    type_map = {
        "xbrl_instance": "xbrl_instance",
        "xbrl_zip": "xbrl_zip",
        "json_financial_api": "json_financial_api",
        "pdf": None,
        "html": "html_report_section",
        "other": "other_attachment",
    }
    store_type_filter = None
    if artifact_type is not None:
        store_type_filter = type_map.get(artifact_type)

    def _dt(s):
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    rows = []
    for a in artifacts:
        if resolved_disclosure_id is not None and a.get("disclosure_id") != resolved_disclosure_id:
            continue
        if store_type_filter is not None and a.get("artifact_type") != store_type_filter:
            continue
        if store_type_filter is None and artifact_type is not None:
            # types like pdf cannot be represented in store; return empty
            rows = []
            break
        if parse_status is not None and a.get("parse_status") != parse_status:
            continue
        rows.append(a)

    reverse = sort_v.startswith("-")
    keyf = sort_v[1:] if reverse else sort_v
    if keyf == "created_at":
        rows.sort(key=lambda r: (_dt(r.get("created_at")) or datetime.datetime.min, r.get("id") or ""), reverse=reverse)
    elif keyf == "fetched_at":
        rows.sort(key=lambda r: (_dt(r.get("fetched_at")) or datetime.datetime.min, r.get("id") or ""), reverse=reverse)

    total = len(rows)
    page = rows[offset:offset + limit_v]
    next_off = offset + len(page)
    has_more = next_off < total
    next_cursor = None
    if has_more:
        token = f"offset:{next_off}".encode("utf-8")
        next_cursor = base64.urlsafe_b64encode(token).decode("utf-8").rstrip("=")

    _tool_transition(req_id, "succeeded")
    return {
        "request_id": req_id,
        "data": page,
        "meta": {
            "filters": {
                "disclosure_id": disclosure_id,
                "rcept_no": rcept_no,
                "artifact_type": artifact_type,
                "parse_status": parse_status,
            },
            "sort": sort_v,
            "limit": limit_v,
            "cursor": cursor,
            "total": total,
            "has_more": has_more,
            "next_cursor": next_cursor,
            "latency_ms": int((time.time() - t0) * 1000),
        }
    }

def start_parse_source_artifact(source_artifact_id, force_reparse=None, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0443000" if __import__("os").path.isdir("./environment_mix/0443000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc).isoformat()

    # Prepare tool_requests audit row (received)
    tool_requests = _load("tool_requests.json")
    companies = _load("companies.json")
    disclosures = _load("disclosures.json")
    source_artifacts = _load("source_artifacts.json")

    def _new_id(prefix):
        # Unique enough for local JSON store
        return f"{prefix}_{datetime.datetime.now(datetime.timezone.utc).strftime('%Y%m%d%H%M%S%f')}"
    req_id = _new_id("treq")
    req_row = {
        "id": req_id,
        "tool_name": "search_disclosure",  # placeholder until validated? must be enum; set correctly:
        "input": {"source_artifact_id": source_artifact_id, "force_reparse": force_reparse},
        "resolved_company_id": None,
        "start_date": None,
        "end_date": None,
        "bsns_year": None,
        "reprt_code": None,
        "fs_div": None,
        "statement_type": None,
        "information_type": None,
        "status": "received",
        "http_cache_hit": False,
        "error_message": None,
        "created_at": now,
        "updated_at": now,
    }
    # Fix tool_name to the right enum value; schema enum doesn't list this tool, but audit must record tool call.
    # Since tool_requests.tool_name enum is fixed, we must fail validation if we can't record. But business rule says
    # every tool call must insert a tool_requests row. We'll record under closest internal tool bucket:
    # Use "search_json_financial_data" for ingestion/parsing-related operations.
    req_row["tool_name"] = "search_json_financial_data"

    tool_requests.append(req_row)
    _save("tool_requests.json", tool_requests)

    def _set_req_status(status, error_message=None):
        nonlocal tool_requests, req_row
        now2 = datetime.datetime.now(datetime.timezone.utc).isoformat()
        # reload to avoid clobber concurrent writes in this offline store
        tool_requests = _load("tool_requests.json")
        for r in tool_requests:
            if r.get("id") == req_id:
                r["status"] = status
                r["updated_at"] = now2
                r["error_message"] = error_message
                req_row = r
                break
        _save("tool_requests.json", tool_requests)

    # Validate inputs
    if not isinstance(source_artifact_id, str) or not source_artifact_id.strip():
        _set_req_status("failed", "source_artifact_id must be a non-empty string.")
        return _err("VALIDATION_ERROR", "Invalid source_artifact_id.")
    if force_reparse is None:
        force_reparse = False
    if not isinstance(force_reparse, bool):
        _set_req_status("failed", "force_reparse must be boolean when provided.")
        return _err("VALIDATION_ERROR", "Invalid force_reparse.")

    # Transition request to running
    _set_req_status("running", None)

    # Find artifact
    art = None
    for a in source_artifacts:
        if a.get("id") == source_artifact_id:
            art = a
            break
    if not art:
        _set_req_status("failed", f"source_artifact_id not found: {source_artifact_id}")
        return _err("NOT_FOUND", "Source artifact not found.", source_artifact_id=source_artifact_id)

    # Enforce retention rule: disallow new parsing/extraction writes if disclosure archived
    disc_id = art.get("disclosure_id")
    disc = None
    if not isinstance(disc_id, str) or not disc_id:
        _set_req_status("failed", "Artifact disclosure_id is missing/invalid.")
        return _err("VALIDATION_ERROR", "Artifact has invalid disclosure_id.", source_artifact_id=source_artifact_id)
    for d in disclosures:
        if d.get("id") == disc_id:
            disc = d
            break
    if not disc:
        _set_req_status("failed", f"disclosure not found for artifact: {disc_id}")
        return _err("NOT_FOUND", "Disclosure for artifact not found.", disclosure_id=disc_id)

    comp_id = disc.get("company_id")
    if isinstance(comp_id, str) and comp_id:
        # record resolved_company_id in audit row
        tool_requests = _load("tool_requests.json")
        for r in tool_requests:
            if r.get("id") == req_id:
                r["resolved_company_id"] = comp_id
                r["updated_at"] = datetime.datetime.now(datetime.timezone.utc).isoformat()
                break
        _save("tool_requests.json", tool_requests)

    if disc.get("status") == "archived":
        _set_req_status("failed", "Disclosure is archived; new parsing writes are disallowed.")
        # Map vendor's FAILED_PRECONDITION to our allowed codes -> INVALID_TRANSITION best fits here.
        return _err("INVALID_TRANSITION", "Parsing disallowed for archived disclosure.", disclosure_id=disc_id)

    # Lifecycle transitions for parse_status
    parse_status = art.get("parse_status")
    allowed_values = {"not_parsed", "parsing", "parsed", "parse_failed"}
    if parse_status not in allowed_values:
        _set_req_status("failed", f"Invalid parse_status on artifact: {parse_status}")
        return _err("VALIDATION_ERROR", "Invalid artifact parse_status.", parse_status=parse_status)

    if parse_status == "parsed":
        _set_req_status("failed", "Artifact already parsed; cannot start parsing.")
        return _err("INVALID_TRANSITION", "Artifact is already parsed.", source_artifact_id=source_artifact_id)

    if parse_status == "parsing":
        _set_req_status("failed", "Artifact is already in parsing state.")
        return _err("CONFLICT", "Parsing already in progress.", source_artifact_id=source_artifact_id)

    if parse_status == "parse_failed" and not force_reparse:
        _set_req_status("failed", "Artifact is parse_failed; force_reparse=false.")
        return _err("INVALID_TRANSITION", "Artifact is in parse_failed; set force_reparse=true to retry.", source_artifact_id=source_artifact_id)

    # not_parsed -> parsing OR parse_failed -> parsing (with force_reparse true)
    # Enforce: direct not_parsed->parsed forbidden (we don't do it)
    now3 = datetime.datetime.now(datetime.timezone.utc).isoformat()
    updated = False
    source_artifacts = _load("source_artifacts.json")
    for a in source_artifacts:
        if a.get("id") == source_artifact_id:
            a["parse_status"] = "parsing"
            a["parse_error"] = None
            a["updated_at"] = now3
            # if fetched_at is null, leave it; this tool is about parsing start
            updated = True
            break
    if not updated:
        _set_req_status("failed", "Artifact disappeared during update.")
        return _err("NOT_FOUND", "Source artifact not found.", source_artifact_id=source_artifact_id)
    _save("source_artifacts.json", source_artifacts)

    _set_req_status("succeeded", None)
    latency_ms = int((time.time() - t0) * 1000)

    # Return updated artifact
    art_out = None
    for a in source_artifacts:
        if a.get("id") == source_artifact_id:
            art_out = a
            break
    if not art_out:
        return _err("NOT_FOUND", "Source artifact not found after update.", source_artifact_id=source_artifact_id)

    return {
        "request_id": req_id,
        "status": "parsing",
        "latency_ms": latency_ms,
        "source_artifact": art_out,
    }
